import * as React from 'react';
import { SPHttpClient } from '@microsoft/sp-http';
import styles from './AssetsView.module.scss';
import NavigationButtons from '../NavigationButtons';

export interface IAssetsViewProps {
  spHttpClient: SPHttpClient;
  spHttpClientConfiguration: any;
  webAbsoluteUrl: string;
  onBack: () => void;
  onDashboard: () => void;
}

interface IEmployee {
  Id: number;
  Title: string;
  Email?: string;
  LoginName?: string;
}

interface IAsset {
  Id: number;
  Title?: string;
  AssetID?: string;
  AssetType?: string;
  AssetModel?: string;
  SerialNumber?: string;
  EmpName?: { Id?: number; Title?: string; EMail?: string; };
  AllocatedDate?: string;
  WarrantyExpiry?: string;
  AssetStatus?: string;
  Client?: string;
  ReturnDate?: string;
  HostName?: string;
  OwnedBy?: string;
  AckStatus?: string;
  AckDate?: string;
  Location?: string;
  AssignmentID?: string;
  Own_x002f_Lease?: string | { Value?: string };
}

interface IAssetResponse { value: IAsset[]; }

interface IAssetRow {
  rowId: number;
  assetType: string;
  assetId: string;
  assetModel: string;
  serialNumber: string;
  client: string;
  warrantyExpiry: string;
  ownLease: string;
  ownedBy: string;
  assetStatus: string;
  ackStatus: string;
  location: string;
}

interface IClientEmployee { employee: IEmployee; assets: IAsset[]; }
interface IClientDetail { client: string; employees: IClientEmployee[]; assets: IAsset[]; }
interface ICategoryDetail { category: string; assets: IAsset[]; }

type IWarrantyState = 'expired' | '7days' | '30days' | 'safe' | 'none';
type IDetailMode = 'none' | 'dashboard' | 'client' | 'category';

interface IState {
  assets: IAsset[];
  loading: boolean;
  saving: boolean;
  updatingAssetId: number | null;
  searchText: string;
  employeeResults: IEmployee[];
  selectedEmployee?: IEmployee;
  selectedEmployeeAssets: IAsset[];
  selectedClient?: IClientDetail;
  selectedCategory?: ICategoryDetail;
  detailMode: IDetailMode;
  detailTitle: string;
  detailAssets: IAsset[];
  showSingleAdd: boolean;
  showBulkAdd: boolean;
  singleEmployee?: IEmployee;
  singleEmployeeText: string;
  singleEmployeeResults: IEmployee[];
  singleEmployeeId: string;
  singleAsset: IAssetRow;
  bulkEmployee?: IEmployee;
  bulkEmployeeText: string;
  bulkEmployeeResults: IEmployee[];
  bulkEmployeeId: string;
  bulkAllocatedDate: string;
  bulkRows: IAssetRow[];
  categoryFilter: string;
  clientFilter: string;
  statusFilter: string;
  ownershipFilter: string;
  ownedByFilter: string;
  locationFilter: string;
  showAllCategories: boolean;
  showAllClients: boolean;
  error: string;
  message: string;
}

export default class AssetsView extends React.Component<IAssetsViewProps, IState> {
  private _nextRowId: number = 1;

  public state: IState = {
    assets: [], loading: true, saving: false, updatingAssetId: null,
    searchText: '', employeeResults: [], selectedEmployee: undefined, selectedEmployeeAssets: [],
    selectedClient: undefined, selectedCategory: undefined, detailMode: 'none', detailTitle: '', detailAssets: [],
    showSingleAdd: false, showBulkAdd: false, singleEmployee: undefined, singleEmployeeText: '', singleEmployeeResults: [],
    singleEmployeeId: '', singleAsset: this._createAssetRow(), bulkEmployee: undefined, bulkEmployeeText: '',
    bulkEmployeeResults: [], bulkEmployeeId: '', bulkAllocatedDate: this._todayForInput(),
    bulkRows: [this._createAssetRow(), this._createAssetRow()],
    categoryFilter: 'All', clientFilter: 'All', statusFilter: 'All', ownershipFilter: 'All', ownedByFilter: 'All',
    locationFilter: 'All', showAllCategories: false, showAllClients: false, error: '', message: ''
  };

  public componentDidMount(): void { void this._loadAssets(); }

  private _createAssetRow(): IAssetRow {
    return {
      rowId: this._nextRowId++, assetType: '', assetId: '', assetModel: '', serialNumber: '',
      client: '', warrantyExpiry: '', ownLease: 'Own', ownedBy: 'FinacPlus', assetStatus: 'In Use',
      ackStatus: 'Pending', location: 'Remote'
    };
  }

  private _todayForInput(): string {
    const date = new Date();
    const mm = (date.getMonth() + 1).toString().padStart(2, '0');
    const dd = date.getDate().toString().padStart(2, '0');
    return `${date.getFullYear()}-${mm}-${dd}`;
  }

  private _formatDate(value?: string): string {
    if (!value) return '-';
    const date = new Date(value);
    if (isNaN(date.getTime())) return '-';
    return `${date.getDate().toString().padStart(2, '0')}/${(date.getMonth() + 1).toString().padStart(2, '0')}/${date.getFullYear()}`;
  }

  private _assetIcon(type?: string): string {
    switch (type) {
      case 'Laptop': return '💻';
      case 'Monitor': case 'Monitor 1': case 'Monitor 2': return '🖥️';
      case 'CPU': case 'Desktop': return '🖥';
      case 'Keyboard': return '⌨️';
      case 'Mouse': return '🖱️';
      case 'Headset': return '🎧';
      case 'Webcam': return '📷';
      case 'Docking Station': return '🔌';
      default: return '📦';
    }
  }

  private _displayAssetType(type?: string): string {
    if (type === 'CPU' || type === 'Desktop') return 'Desktop';
    return type || '-';
  }

  private _getOwnershipValue(asset: IAsset): string {
    const value: any = asset.Own_x002f_Lease;
    if (!value) return '';
    if (typeof value === 'string') return value.trim();
    if (value.Value) return String(value.Value).trim();
    return String(value).trim();
  }

  private _getWarrantyState(value?: string): IWarrantyState {
    if (!value) return 'none';
    const expiry = new Date(value);
    if (isNaN(expiry.getTime())) return 'none';
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    expiry.setHours(0, 0, 0, 0);
    const days = Math.ceil((expiry.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
    if (days < 0) return 'expired';
    if (days <= 7) return '7days';
    if (days <= 30) return '30days';
    return 'safe';
  }

  private _warrantyLabel(value?: string): string {
    switch (this._getWarrantyState(value)) {
      case 'expired': return 'Expired';
      case '7days': return 'Expires <= 7 days';
      case '30days': return 'Expires <= 30 days';
      case 'safe': return 'Valid';
      default: return 'No Warranty Date';
    }
  }

  private _warrantyClass(value?: string): string {
    switch (this._getWarrantyState(value)) {
      case 'expired': return styles.warranty_expired;
      case '7days': return styles.warranty_7days;
      case '30days': return styles.warranty_30days;
      case 'safe': return styles.warranty_safe;
      default: return styles.warranty_none;
    }
  }

  private _countOwnedAssets(assets: IAsset[]): number {
    return assets.filter(asset => this._getOwnershipValue(asset).toLowerCase() === 'own').length;
  }

  private _countLeasedAssets(assets: IAsset[]): number {
    return assets.filter(asset => {
      const val = this._getOwnershipValue(asset).toLowerCase();
      return val === 'lease' || val === 'leased';
    }).length;
  }

  private _countWarranty30Days(assets: IAsset[]): number { return assets.filter(a => this._getWarrantyState(a.WarrantyExpiry) === '30days').length; }
  private _countWarranty7Days(assets: IAsset[]): number { return assets.filter(a => this._getWarrantyState(a.WarrantyExpiry) === '7days').length; }
  private _countWarrantyExpired(assets: IAsset[]): number { return assets.filter(a => this._getWarrantyState(a.WarrantyExpiry) === 'expired').length; }
  private _getActiveAssets(): IAsset[] { return this.state.assets.filter(a => a.AssetStatus === 'In Use'); }
  private _getClientAssets(client: string): IAsset[] { return this._getActiveAssets().filter(a => a.Client === client); }
  private _getCategoryAssets(category: string): IAsset[] {
    if (category === 'Desktop') return this._getActiveAssets().filter(a => a.AssetType === 'CPU' || a.AssetType === 'Desktop');
    return this._getActiveAssets().filter(a => a.AssetType === category);
  }

  private _getAssetTypes(): string[] {
    const preferred = ['Laptop', 'Monitor', 'Keyboard', 'Mouse', 'Headset', 'Docking Station', 'CPU', 'Desktop'];
    const discovered: string[] = [];
    this.state.assets.forEach(a => {
      const type = (a.AssetType || '').trim();
      if (type && discovered.indexOf(type) === -1) discovered.push(type);
    });
    const ordered: string[] = [];
    preferred.forEach(item => {
      const exact = discovered.find(v => v.toLowerCase() === item.toLowerCase());
      if (exact && ordered.indexOf(exact) === -1) {
        if (exact === 'CPU' || exact === 'Desktop') {
          if (ordered.indexOf('CPU') === -1 && ordered.indexOf('Desktop') === -1) ordered.push(exact);
        } else {
          ordered.push(exact);
        }
      }
    });
    return ordered.concat(discovered.filter(v => ordered.indexOf(v) === -1).sort((a, b) => a.localeCompare(b)));
  }

  private _getClients(): string[] {
    const values: string[] = [];
    this.state.assets.forEach(a => { const c = (a.Client || '').trim(); if (c && values.indexOf(c) === -1) values.push(c); });
    return values.sort();
  }

  private _getStatuses(): string[] {
    const values: string[] = [];
    this.state.assets.forEach(a => { const s = (a.AssetStatus || '').trim(); if (s && values.indexOf(s) === -1) values.push(s); });
    return values.sort();
  }

  private _getEmployees(): IEmployee[] {
    const result: IEmployee[] = [];
    const ids: number[] = [];
    this._getActiveAssets().forEach(a => {
      const id = a.EmpName && a.EmpName.Id ? a.EmpName.Id : 0;
      if (id && ids.indexOf(id) === -1) {
        ids.push(id);
        result.push({ Id: id, Title: (a.EmpName && a.EmpName.Title) || 'Unknown User', Email: (a.EmpName && a.EmpName.EMail) || '' });
      }
    });
    return result.sort((a, b) => a.Title.localeCompare(b.Title));
  }

  private _getEmployeeAssets(employeeId: number): IAsset[] { return this._getActiveAssets().filter(a => Number(a.EmpName && a.EmpName.Id) === Number(employeeId)); }
  private _getEmployeeId(assets: IAsset[]): string { const found = assets.find(a => !!a.Title); return found && found.Title ? found.Title : '-'; }
  
  private _getEmployeeClients(assets: IAsset[]): string[] {
    const values: string[] = [];
    assets.forEach(a => { const c = (a.Client || '').trim(); if (c && values.indexOf(c) === -1) values.push(c); });
    return values.sort();
  }

  private _getEmployeeLocations(assets: IAsset[]): string[] {
    const values: string[] = [];
    assets.forEach(a => { const l = (a.Location || '').trim(); if (l && values.indexOf(l) === -1) values.push(l); });
    return values.sort();
  }

  private _countType(assets: IAsset[], type: string): number {
    if (type === 'Desktop' || type === 'CPU') return assets.filter(a => a.AssetType === 'CPU' || a.AssetType === 'Desktop').length;
    return assets.filter(a => a.AssetType === type).length;
  }

  private _getClientEmployees(client: string): IClientEmployee[] {
    const result: IClientEmployee[] = [];
    const ids: number[] = [];
    this._getClientAssets(client).forEach(asset => {
      const id = asset.EmpName && asset.EmpName.Id ? asset.EmpName.Id : 0;
      if (id && ids.indexOf(id) === -1) {
        ids.push(id);
        result.push({
          employee: { Id: id, Title: (asset.EmpName && asset.EmpName.Title) || 'Unknown User', Email: (asset.EmpName && asset.EmpName.EMail) || '' },
          assets: this._getEmployeeAssets(id)
        });
      }
    });
    return result.sort((a, b) => a.employee.Title.localeCompare(b.employee.Title));
  }

  private _getClientDetail(client: string): IClientDetail { return { client, employees: this._getClientEmployees(client), assets: this._getClientAssets(client) }; }
  private _getCategoryDetail(category: string): ICategoryDetail { return { category, assets: this._getCategoryAssets(category) }; }
  private _getPercentage(value: number, total: number): string { return !total ? '0%' : ((value / total) * 100).toFixed(1) + '%'; }

  private _loadAssets = async (): Promise<void> => {
    this.setState({ loading: true, error: '' });
    try {
      const url = `${this.props.webAbsoluteUrl}/_api/web/lists/getbytitle('Active IT Assets')/items?$select=Id,Title,AssetID,AssetType,AssetModel,SerialNumber,EmpName/Id,EmpName/Title,EmpName/EMail,AllocatedDate,WarrantyExpiry,AssetStatus,Client,ReturnDate,HostName,OwnedBy,AckStatus,AckDate,Location,AssignmentID,Own_x002f_Lease&$expand=EmpName&$orderby=Id desc&$top=5000`;
      const response = await this.props.spHttpClient.get(url, this.props.spHttpClientConfiguration, { headers: { Accept: 'application/json;odata=nometadata' } });
      if (!response.ok) throw new Error(`Active IT Assets returned ${response.status}. ${await response.text()}`);
      const data: IAssetResponse = await response.json();
      this.setState({ assets: data.value || [], loading: false, error: '' });
    } catch (error) {
      this.setState({ loading: false, error: error instanceof Error ? error.message : 'Unable to load Active IT Assets.' });
    }
  };

  private _searchUsers = async (value: string): Promise<IEmployee[]> => {
    const text = value.trim().toLowerCase();
    const url = `${this.props.webAbsoluteUrl}/_api/web/siteusers?$select=Id,Title,Email,LoginName&$top=5000`;
    const response = await this.props.spHttpClient.get(url, this.props.spHttpClientConfiguration, { headers: { Accept: 'application/json;odata=nometadata' } });
    if (!response.ok) throw new Error(`User search returned ${response.status}.`);
    const data = await response.json();
    return (data.value || [])
      .filter((user: any) => {
        const name = String(user.Title || '').toLowerCase();
        const email = String(user.Email || '').toLowerCase();
        return name.indexOf(text) !== -1 || email.indexOf(text) !== -1;
      })
      .slice(0, 20)
      .map((user: any) => ({ Id: Number(user.Id), Title: user.Title || '', Email: user.Email || '', LoginName: user.LoginName || '' }));
  };

  private _employeeSearch = async (value: string): Promise<void> => {
    this.setState({ searchText: value, selectedEmployee: undefined, selectedEmployeeAssets: [], detailMode: 'none', employeeResults: [], error: '' });
    if (!value.trim()) return;
    try { this.setState({ employeeResults: await this._searchUsers(value) }); } 
    catch (error) { this.setState({ employeeResults: [], error: error instanceof Error ? error.message : 'Unable to search users.' }); }
  };

  private _selectEmployee = (employee: IEmployee): void => {
    this.setState({ selectedEmployee: employee, selectedEmployeeAssets: this._getEmployeeAssets(employee.Id), searchText: employee.Title, employeeResults: [], detailMode: 'none', error: '', message: '' });
  };

  private _clearEmployee = (): void => {
    this.setState({ searchText: '', employeeResults: [], selectedEmployee: undefined, selectedEmployeeAssets: [], detailMode: 'none', error: '' });
  };

  private _openDashboardDetail = (title: string, assets: IAsset[]): void => {
    this.setState({ detailMode: 'dashboard', detailTitle: title, detailAssets: assets, selectedEmployee: undefined, searchText: '', employeeResults: [], error: '' });
  };

  private _closeDetail = (): void => { this.setState({ detailMode: 'none', detailTitle: '', detailAssets: [] }); };

  private _openClient = (client: string): void => {
    this.setState({ selectedClient: this._getClientDetail(client), detailMode: 'client', detailTitle: client, detailAssets: this._getClientAssets(client), searchText: '', employeeResults: [], error: '' });
  };

  private _openCategory = (category: string): void => {
    this.setState({ selectedCategory: this._getCategoryDetail(category), detailMode: 'category', detailTitle: category, detailAssets: this._getCategoryAssets(category), searchText: '', employeeResults: [], error: '' });
  };

  private _openSingleAdd = (): void => {
    const emp = this.state.selectedEmployee;
    this.setState({ showSingleAdd: true, showBulkAdd: false, singleEmployee: emp, singleEmployeeText: emp ? emp.Title : '', singleEmployeeResults: [], singleEmployeeId: this._getEmployeeId(emp ? this._getEmployeeAssets(emp.Id) : []), singleAsset: this._createAssetRow(), error: '', message: '' });
  };

  private _closeSingleAdd = (): void => { this.setState({ showSingleAdd: false, singleEmployee: undefined, singleEmployeeText: '', singleEmployeeResults: [], singleEmployeeId: '', error: '' }); };

  private _openBulkAdd = (): void => {
    const emp = this.state.selectedEmployee;
    this.setState({ showBulkAdd: true, showSingleAdd: false, bulkEmployee: emp, bulkEmployeeText: emp ? emp.Title : '', bulkEmployeeResults: [], bulkEmployeeId: this._getEmployeeId(emp ? this._getEmployeeAssets(emp.Id) : []), bulkAllocatedDate: this._todayForInput(), bulkRows: [this._createAssetRow(), this._createAssetRow()], error: '', message: '' });
  };

  private _closeBulkAdd = (): void => { this.setState({ showBulkAdd: false, bulkEmployee: undefined, bulkEmployeeText: '', bulkEmployeeResults: [], bulkEmployeeId: '', bulkRows: [this._createAssetRow(), this._createAssetRow()], error: '' }); };

  private _singleEmployeeSearch = async (value: string): Promise<void> => {
    this.setState({ singleEmployeeText: value, singleEmployeeResults: [] });
    if (!value.trim()) return;
    try { this.setState({ singleEmployeeResults: await this._searchUsers(value) }); } catch { this.setState({ singleEmployeeResults: [] }); }
  };

  private _bulkEmployeeSearch = async (value: string): Promise<void> => {
    this.setState({ bulkEmployeeText: value, bulkEmployeeResults: [] });
    if (!value.trim()) return;
    try { this.setState({ bulkEmployeeResults: await this._searchUsers(value) }); } catch { this.setState({ bulkEmployeeResults: [] }); }
  };

  private _selectSingleEmployee = (employee: IEmployee): void => {
    this.setState({ singleEmployee: employee, singleEmployeeText: employee.Title, singleEmployeeResults: [], singleEmployeeId: this._getEmployeeId(this._getEmployeeAssets(employee.Id)), error: '' });
  };

  private _selectBulkEmployee = (employee: IEmployee): void => {
    this.setState({ bulkEmployee: employee, bulkEmployeeText: employee.Title, bulkEmployeeResults: [], bulkEmployeeId: this._getEmployeeId(this._getEmployeeAssets(employee.Id)), error: '' });
  };

  private _updateSingleAsset = (field: keyof IAssetRow, value: string): void => { this.setState({ singleAsset: { ...this.state.singleAsset, [field]: value } }); };
  private _updateBulkRow = (rowId: number, field: keyof IAssetRow, value: string): void => {
    this.setState({ bulkRows: this.state.bulkRows.map(row => (row.rowId === rowId ? { ...row, [field]: value } : row)) });
  };

  private _addBulkRow = (): void => { this.setState({ bulkRows: this.state.bulkRows.concat([this._createAssetRow()]) }); };
  private _removeBulkRow = (rowId: number): void => {
    if (this.state.bulkRows.length <= 1) return;
    this.setState({ bulkRows: this.state.bulkRows.filter(row => row.rowId !== rowId) });
  };

  private _validateAsset(row: IAssetRow): string {
    if (!row.assetType.trim()) return 'Asset Type is required.';
    if (!row.assetId.trim()) return 'Asset ID is required.';
    if (!row.client.trim()) return 'Client is required.';
    if (!row.ownLease.trim()) return 'Ownership is required.';
    if (!row.ownedBy.trim()) return 'Owned By is required.';
    if (!row.location.trim()) return 'Location is required.';
    return '';
  }

  private _createAsset = async (row: IAssetRow, employee: IEmployee, employeeId: string, allocatedDate: string): Promise<void> => {
    const payload: any = {
      Title: employeeId, EmpNameId: employee.Id, AssetID: row.assetId, AssetType: row.assetType, AssetModel: row.assetModel, SerialNumber: row.serialNumber, Client: row.client, AllocatedDate: allocatedDate, WarrantyExpiry: row.warrantyExpiry || null, 'Own_x002f_Lease': row.ownLease, OwnedBy: row.ownedBy, Location: row.location, AssetStatus: row.assetStatus, AckStatus: row.ackStatus, AssignmentID: `ASSIGN-${Date.now()}-${row.rowId}`
    };
    const url = `${this.props.webAbsoluteUrl}/_api/web/lists/getbytitle('Active IT Assets')/items`;
    const response = await this.props.spHttpClient.post(url, this.props.spHttpClientConfiguration, {
      headers: { Accept: 'application/json;odata=nometadata', 'Content-Type': 'application/json;odata=nometadata' },
      body: JSON.stringify(payload)
    });
    if (!response.ok) throw new Error(`Unable to create asset ${row.assetId}`);
  };

  private _saveSingleAsset = async (): Promise<void> => {
    const employee = this.state.singleEmployee;
    if (!employee || !employee.Id) return this.setState({ error: 'Select an exact Microsoft 365 employee.' });
    if (!this.state.singleEmployeeId.trim()) return this.setState({ error: 'Employee ID is required.' });
    
    const validation = this._validateAsset(this.state.singleAsset);
    if (validation) return this.setState({ error: validation });

    this.setState({ saving: true, error: '', message: '' });
    try {
      await this._createAsset(this.state.singleAsset, employee, this.state.singleEmployeeId, this._todayForInput());
      await this._loadAssets();
      this.setState({ saving: false, showSingleAdd: false, selectedEmployee: employee, selectedEmployeeAssets: this._getEmployeeAssets(employee.Id), message: 'Asset added successfully.' });
    } catch (error) { this.setState({ saving: false, error: error instanceof Error ? error.message : 'Unable to add asset.' }); }
  };

  private _saveBulkAssets = async (): Promise<void> => {
    const employee = this.state.bulkEmployee;
    if (!employee || !employee.Id) return this.setState({ error: 'Select an exact Microsoft 365 employee.' });
    if (!this.state.bulkEmployeeId.trim()) return this.setState({ error: 'Employee ID is required.' });

    let validation = '';
    this.state.bulkRows.some(row => { validation = this._validateAsset(row); return validation !== ''; });
    if (validation) return this.setState({ error: validation });

    this.setState({ saving: true, error: '', message: '' });
    try {
      for (const row of this.state.bulkRows) await this._createAsset(row, employee, this.state.bulkEmployeeId, this.state.bulkAllocatedDate);
      await this._loadAssets();
      this.setState({ saving: false, showBulkAdd: false, selectedEmployee: employee, selectedEmployeeAssets: this._getEmployeeAssets(employee.Id), message: `${this.state.bulkRows.length} asset(s) assigned successfully.` });
    } catch (error) { this.setState({ saving: false, error: error instanceof Error ? error.message : 'Unable to assign assets.' }); }
  };

  private _updateAssetStatus = async (assetId: number, status: string): Promise<void> => {
    this.setState({ updatingAssetId: assetId, error: '', message: '' });
    try {
      const payload: any = { AssetStatus: status };
      if (status === 'Returned to Vendor') payload.ReturnDate = this._todayForInput();
      const url = `${this.props.webAbsoluteUrl}/_api/web/lists/getbytitle('Active IT Assets')/items(${assetId})`;
      const response = await this.props.spHttpClient.post(url, this.props.spHttpClientConfiguration, {
        headers: { Accept: 'application/json;odata=nometadata', 'Content-Type': 'application/json;odata=nometadata', 'IF-MATCH': '*', 'X-HTTP-Method': 'MERGE' },
        body: JSON.stringify(payload)
      });
      if (!response.ok) throw new Error('Unable to update asset status.');
      await this._loadAssets();
      
      let detailAssets = this.state.detailAssets;
      if (this.state.detailMode === 'dashboard') detailAssets = this._getActiveAssets();
      else if (this.state.detailMode === 'client') detailAssets = this._getClientAssets(this.state.detailTitle);
      else if (this.state.detailMode === 'category') detailAssets = this._getCategoryAssets(this.state.detailTitle);

      this.setState({ updatingAssetId: null, selectedEmployeeAssets: this.state.selectedEmployee ? this._getEmployeeAssets(this.state.selectedEmployee.Id) : [], detailAssets, message: status === 'Returned to Vendor' ? 'Asset marked as Returned to Vendor.' : 'Asset status updated.' });
    } catch (error) { this.setState({ updatingAssetId: null, error: error instanceof Error ? error.message : 'Unable to update asset status.' }); }
  };

  private _resetFilters = (): void => { this.setState({ categoryFilter: 'All', clientFilter: 'All', statusFilter: 'All', ownershipFilter: 'All', ownedByFilter: 'All', locationFilter: 'All' }); };

  private _renderWarranty(value?: string): React.ReactElement<{}> {
    return (
      <div className={styles.warrantyInfo}>
        <strong>{this._formatDate(value)}</strong>
        <span className={this._warrantyClass(value)}>{this._warrantyLabel(value)}</span>
      </div>
    );
  }

  public render(): React.ReactElement<IAssetsViewProps> {
    const { assets, activeAssets = this._getActiveAssets(), employees = this._getEmployees(), clients = this._getClients(), assetTypes = this._getAssetTypes(), statuses = this._getStatuses() } = this.state as any;
    const activeCount = this._getActiveAssets().length;
    const employeeMode = this.state.searchText.trim().length > 0 || !!this.state.selectedEmployee;

    return (
      <div className={styles.page}>
        <div className={styles.pageHeader}>
          <div className={styles.brandLine}>
            <span className={styles.brandIcon}>◈</span>
            <div>
              <div className={styles.brandTitle}>Asset Management</div>
              <div className={styles.brandSubtitle}>Hardware &amp; IT Inventory Hub</div>
            </div>
          </div>
          <NavigationButtons onDashboard={this.props.onDashboard} onBack={this.props.onBack} backLabel="Back" />
        </div>

        <div className={styles.actionHeader}>
          <div>
            <h1>Master Asset Inventory</h1>
            <p className={styles.subtitle}>Central view of employee hardware and client allocations.</p>
          </div>
          <div className={styles.topActions}>
            <button type="button" className={styles.secondaryTopButton} onClick={this._openBulkAdd}>⊞ Add Multiple Assets</button>
            <button type="button" className={styles.primaryTopButton} onClick={this._openSingleAdd}>＋ Add Asset</button>
          </div>
        </div>

        {this.state.error && <div className={styles.error}>{this.state.error}</div>}
        {this.state.message && <div className={styles.success}>{this.state.message}</div>}

        <div className={styles.filterPanel}>
          <div className={styles.searchBox}>
            <span>🔎</span>
            <input type="text" value={this.state.searchText} onChange={e => void this._employeeSearch(e.target.value)} placeholder="Search employees..." />
            {this.state.searchText && <button type="button" className={styles.searchClear} onClick={this._clearEmployee}>×</button>}
          </div>

          {!employeeMode && (
            <div className={styles.filtersRow}>
              <select value={this.state.categoryFilter} onChange={e => this.setState({ categoryFilter: e.target.value })}>
                <option value="All">All Categories ({assetTypes.length})</option>
                {assetTypes.map((type: string) => <option key={type} value={type}>{this._displayAssetType(type)}</option>)}
              </select>
              <select value={this.state.clientFilter} onChange={e => this.setState({ clientFilter: e.target.value })}>
                <option value="All">All Clients ({clients.length})</option>
                {clients.map((client: string) => <option key={client} value={client}>{client}</option>)}
              </select>
              <select value={this.state.statusFilter} onChange={e => this.setState({ statusFilter: e.target.value })}>
                <option value="All">All Statuses</option>
                {statuses.map((status: string) => <option key={status} value={status}>{status}</option>)}
              </select>
              <select value={this.state.ownershipFilter} onChange={e => this.setState({ ownershipFilter: e.target.value })}>
                <option value="All">All Ownership</option>
                <option value="Own">Own</option>
                <option value="Leased">Leased</option>
              </select>
              <select value={this.state.ownedByFilter} onChange={e => this.setState({ ownedByFilter: e.target.value })}>
                <option value="All">All Owned By</option>
                <option value="FinacPlus">FinacPlus</option>
                <option value="SixSigma">SixSigma</option>
              </select>
              <button type="button" className={styles.resetButton} onClick={this._resetFilters}>Reset Filters</button>
            </div>
          )}
        </div>

        {this.state.employeeResults.length > 0 && (
          <div className={styles.peopleDropdown}>
            {this.state.employeeResults.map(employee => (
              <button key={employee.Email || employee.Title} type="button" onClick={() => this._selectEmployee(employee)}>
                <span className={styles.peopleAvatar}>{(employee.Title || 'U').substring(0, 1).toUpperCase()}</span>
                <span>
                  <strong>{employee.Title}</strong>
                  <small>{employee.Email || employee.LoginName || ''}</small>
                </span>
              </button>
            ))}
          </div>
        )}

        {employeeMode && this.state.selectedEmployee && (
          <div className={styles.employeeProfilePage}>
            <div className={styles.employeeProfileHeader}>
              <div className={styles.employeeIdentityLarge}>
                <div className={styles.employeeAvatarProfile}>
                  {(this.state.selectedEmployee.Title || 'U').substring(0, 1).toUpperCase()}
                </div>
                <div>
                  <div className={styles.detailEyebrow}>EMPLOYEE ASSET PROFILE</div>
                  <h2>{this.state.selectedEmployee.Title}</h2>
                  <p>{this.state.selectedEmployee.Email || ''}</p>
                </div>
              </div>
            </div>

            <div className={styles.profileStats}>
              <div><span>Employee ID</span><strong>{this._getEmployeeId(this.state.selectedEmployeeAssets)}</strong></div>
              <div><span>Client</span><strong>{this._getEmployeeClients(this.state.selectedEmployeeAssets).join(', ') || '-'}</strong></div>
              <div><span>Location</span><strong>{this._getEmployeeLocations(this.state.selectedEmployeeAssets).join(', ') || '-'}</strong></div>
              <div><span>Total Assets</span><strong>{this.state.selectedEmployeeAssets.length}</strong></div>
            </div>

            <div className={styles.employeeAssetSection}>
              <div className={styles.employeeSectionHeader}>
                <h2>Assigned Assets</h2>
                <button type="button" className={styles.secondaryTopButton} onClick={this._clearEmployee}>← Back</button>
              </div>

              {this.state.selectedEmployeeAssets.length === 0 ? (
                <div className={styles.categoryEmpty}>No active assets assigned.</div>
              ) : (
                <div className={styles.employeeAssetGrid}>
                  {this.state.selectedEmployeeAssets.map(asset => (
                    <div key={asset.Id} className={styles.employeeAssetCard}>
                      <div className={styles.employeeAssetIconLarge}>{this._assetIcon(asset.AssetType)}</div>
                      <div className={styles.employeeAssetMain}>
                        <strong>{this._displayAssetType(asset.AssetType)}</strong>
                        <span>{asset.AssetID || '-'}</span>
                      </div>
                      <div className={styles.employeeAssetDetails}>
                        <span>Serial: {asset.SerialNumber || '-'}</span>
                        {this._renderWarranty(asset.WarrantyExpiry)}
                      </div>
                      <div className={styles.employeeAssetLocation}>
                        <span>Location: {asset.Location || '-'}</span>
                        <button type="button" className={styles.returnVendorButton} disabled={this.state.updatingAssetId === asset.Id} onClick={() => void this._updateAssetStatus(asset.Id, 'Returned to Vendor')}>
                          {this.state.updatingAssetId === asset.Id ? 'Updating...' : 'Return'}
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        )}

        {!employeeMode && this.state.detailMode === 'none' && (
          <React.Fragment>
            <div className={styles.kpiGrid}>
              <button type="button" className={`${styles.kpiCard} ${styles.blueCard}`} onClick={() => this._openDashboardDetail('Total Assets', this._getActiveAssets())}>
                <div className={styles.kpiIcon}>◈</div><span>Total Assets</span><strong>{this.state.assets.length.toLocaleString()}</strong>
              </button>
              <button type="button" className={`${styles.kpiCard} ${styles.greenCard}`} onClick={() => this._openDashboardDetail('Active Units', this._getActiveAssets())}>
                <div className={styles.kpiIcon}>✓</div><span>Active Units</span><strong>{activeCount.toLocaleString()}</strong>
              </button>
              <button type="button" className={`${styles.kpiCard} ${styles.purpleCard}`} onClick={() => this._openDashboardDetail('Employees', this._getActiveAssets())}>
                <div className={styles.kpiIcon}>◎</div><span>Employees</span><strong>{this._getEmployees().length.toLocaleString()}</strong>
              </button>
              <button type="button" className={`${styles.kpiCard} ${styles.orangeCard}`} onClick={() => this._openDashboardDetail('Laptops', this._getCategoryAssets('Laptop'))}>
                <div className={styles.kpiIcon}>💻</div><span>Laptops</span><strong>{this._countType(this._getActiveAssets(), 'Laptop').toLocaleString()}</strong>
              </button>
            </div>

            <div className={styles.dashboardGrid}>
              <div className={styles.categoryPanel}>
                <div className={styles.panelHeader}>
                  <div><h2>Assets by Category</h2><span className={styles.subtitle}>Click to view assets.</span></div>
                </div>
                <div className={styles.categoryList}>
                  {this._getAssetTypes().map(type => {
                    const count = this._countType(this._getActiveAssets(), type);
                    return (
                      <button key={type} type="button" className={styles.categoryItemButton} onClick={() => this._openCategory(type)}>
                        <div className={styles.categoryItem}>
                          <div className={styles.categoryItemIcon}>{this._assetIcon(type)}</div>
                          <div className={styles.categoryItemMain}>
                            <div className={styles.categoryItemTop}><span>{type}</span><strong>{count}</strong></div>
                            <div className={styles.progressTrack}><div className={styles.progressFill} style={{ width: this._getPercentage(count, activeCount) }} /></div>
                          </div>
                        </div>
                      </button>
                    );
                  })}
                </div>
              </div>

              <div className={styles.clientPanel}>
                <div className={styles.panelHeader}>
                  <div><h2>Client Wise Assets</h2><span className={styles.subtitle}>View distribution.</span></div>
                </div>
                <div className={styles.clientSummaryGrid}>
                  {this._getClients().map(client => {
                    const count = this._getClientAssets(client).length;
                    return (
                      <button key={client} type="button" className={styles.clientSummaryCard} onClick={() => this._openClient(client)}>
                        <div className={styles.clientSummaryTop}><span>{client}</span><strong>{count}</strong></div>
                        <div className={styles.progressTrack}><div className={styles.clientProgress} style={{ width: this._getPercentage(count, activeCount) }} /></div>
                      </button>
                    );
                  })}
                </div>
              </div>
            </div>
          </React.Fragment>
        )}

        {this.state.showBulkAdd && (
          <div className={styles.modalOverlay}>
            <div className={styles.assetModalWide}>
              <div className={styles.modalHeader}>
                <div>
                  <div className={styles.detailEyebrow}>BATCH ASSIGNMENT</div>
                  <h2>Add Multiple Assets for a User</h2>
                </div>
                <button type="button" className={styles.detailClose} onClick={this._closeBulkAdd}>×</button>
              </div>

              <div className={styles.modalBody}>
                <div className={styles.assignmentSection}>
                  <div className={styles.assignmentSectionHeader}>1. Allocation Details</div>
                  <div className={styles.formGridFour}>
                    <div className={styles.formGroup}>
                      <label>Employee / User Name *</label>
                      <input value={this.state.bulkEmployeeText} onChange={e => void this._bulkEmployeeSearch(e.target.value)} placeholder="Search user" />
                      {this.state.bulkEmployeeResults.length > 0 && (
                        <div className={styles.peopleDropdownInside}>
                          {this.state.bulkEmployeeResults.map(emp => (
                            <button key={emp.Id} type="button" onClick={() => this._selectBulkEmployee(emp)}>
                              <strong>{emp.Title}</strong><small>{emp.Email}</small>
                            </button>
                          ))}
                        </div>
                      )}
                    </div>
                    <div className={styles.formGroup}><label>Employee ID</label><input value={this.state.bulkEmployeeId} onChange={e => this.setState({ bulkEmployeeId: e.target.value })} /></div>
                    <div className={styles.formGroup}><label>Client Account</label>
                      <select value={this.state.bulkRows[0]?.client || ''} onChange={e => this.setState({ bulkRows: this.state.bulkRows.map(r => ({ ...r, client: e.target.value })) })}>
                        <option value="">Select</option>{this._getClients().map(c => <option key={c} value={c}>{c}</option>)}
                      </select>
                    </div>
                    <div className={styles.formGroup}><label>Allocation Date</label><input type="date" value={this.state.bulkAllocatedDate} onChange={e => this.setState({ bulkAllocatedDate: e.target.value })} /></div>
                  </div>
                </div>

                <div className={styles.assignmentSection}>
                  <div className={styles.assignmentSectionHeader}>
                    <div>2. Equipment to Assign</div>
                    <div className={styles.quickButtons}>
                      <button type="button" onClick={() => this.setState({ bulkRows: this.state.bulkRows.concat([{ ...this._createAssetRow(), assetType: 'Laptop' }]) })}>＋ Laptop</button>
                      <button type="button" onClick={() => this.setState({ bulkRows: this.state.bulkRows.concat([{ ...this._createAssetRow(), assetType: 'Monitor' }]) })}>＋ Monitor</button>
                    </div>
                  </div>

                  <div className={styles.bulkTable}>
                    <div className={styles.bulkHeader}>
                      <span>#</span><span>Category *</span><span>Asset ID *</span><span>Serial No</span><span>Model/Details</span><span>Warranty</span><span>Status</span><span></span>
                    </div>
                    {this.state.bulkRows.map((row, index) => (
                      <div key={row.rowId} className={styles.bulkRow}>
                        <span className={styles.rowNumber}>{index + 1}</span>
                        <select value={row.assetType} onChange={e => this._updateBulkRow(row.rowId, 'assetType', e.target.value)}>
                          <option value="">Select</option>{this._getAssetTypes().map(t => <option key={t} value={t}>{t}</option>)}
                        </select>
                        <input value={row.assetId} onChange={e => this._updateBulkRow(row.rowId, 'assetId', e.target.value)} placeholder="Asset ID" />
                        <input value={row.serialNumber} onChange={e => this._updateBulkRow(row.rowId, 'serialNumber', e.target.value)} placeholder="Serial" />
                        <input value={row.assetModel} onChange={e => this._updateBulkRow(row.rowId, 'assetModel', e.target.value)} placeholder="Model" />
                        <input type="date" value={row.warrantyExpiry} onChange={e => this._updateBulkRow(row.rowId, 'warrantyExpiry', e.target.value)} />
                        <select value={row.assetStatus} onChange={e => this._updateBulkRow(row.rowId, 'assetStatus', e.target.value)}><option value="In Use">In Use</option></select>
                        <button type="button" className={styles.deleteRow} onClick={() => this._removeBulkRow(row.rowId)} disabled={this.state.bulkRows.length <= 1}>🗑</button>
                      </div>
                    ))}
                  </div>
                  <button type="button" className={styles.addAnotherRow} onClick={this._addBulkRow}>＋ Add Row</button>
                </div>
              </div>

              <div className={styles.modalFooter}>
                <span className={styles.footerInfo}>All rows link to the selected employee.</span>
                <div className={styles.modalFooterRight}>
                  <button type="button" className={styles.cancelButton} onClick={this._closeBulkAdd}>Cancel</button>
                  <button type="button" className={styles.saveButton} onClick={this._saveBulkAssets} disabled={this.state.saving}>
                    {this.state.saving ? 'Saving...' : `Assign ${this.state.bulkRows.length} Assets`}
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    );
  }
}